const page=document.body.dataset.page||'home';
document.body.classList.add('cinematic-site','painted-site');
const icon=(key,cls='')=>{const paths={
 agua:'<path d="M16 3C12 9 5 15 5 21a11 11 0 0 0 22 0C27 15 20 9 16 3Z"/><path d="M10 22c0 4 3 6 6 6"/>',
 terra:'<path d="m3 27 7-20h14l5 20Z"/><path d="m9 27 4-13h7l3 13M12 22h10"/>',
 fogo:'<path d="M18 3c3 9-4 9 1 15 2-1 3-3 3-6 8 8 6 17-5 18C5 30 2 21 8 14c0 4 2 5 3 6C10 12 17 10 18 3Z"/>',
 ar:'<path d="M3 12h18c8 0 7-10 1-9-4 0-5 5-2 6M2 18h22c8 0 7 11 0 11-4 0-5-5-2-6M5 24h8c5 0 5 6 0 6"/>',
 compass:'<circle cx="16" cy="16" r="12"/><path d="m22 10-4 8-8 4 4-8Z"/>',
 search:'<circle cx="13" cy="13" r="8"/><path d="m19 19 9 9"/>',
 arrow:'<path d="M5 16h22M19 8l8 8-8 8"/>',
 star:'<path d="m16 2 3.5 10.5L30 16l-10.5 3.5L16 30l-3.5-10.5L2 16l10.5-3.5Z"/>'};return `<svg class="symbol ${cls}" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[key]||paths.star}</svg>`};
const link=(key)=>`<a class="source-link" href="${SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${SOURCES[key].label} ↗</a>`;
const sources=(keys)=>`<aside class="sources"><span class="eyebrow">CONSULTE AS FONTES OFICIAIS</span><div>${[...new Set(keys)].map(link).join('')}</div></aside>`;
const pic=(name,alt,cls='',eager=false)=>`<img class="${cls}" src="assets/${name}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="1024" height="576">`;
const sectionHead=(eyebrow,title,extra='')=>`<div class="section-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${extra}</div>`;
const navItem=(href,label,id)=>`<a href="${href}" ${page===id?'aria-current="page"':''}>${label}</a>`;
const elementNav=()=>Object.entries(ELEMENTS).map(([key,e])=>`<a href="${key}.html" class="element-pill ${key} ${page===key?'selected':''}" ${page===key?'aria-current="page"':''}>${icon(key)} ${e.name}</a>`).join('');
document.querySelector('#header').innerHTML=`<div class="header-inner"><a class="brand" href="index.html" aria-label="Atlas Avatar — início">${icon('compass')}<span>ATLAS <b>AVATAR</b><small>UM MUNDO DE HISTÓRIAS</small></span></a><nav aria-label="Principal">${navItem('index.html','O universo','home')}${navItem('historia.html','A história','historia')}<a href="index.html#elementos" ${ELEMENTS[page]?'aria-current="page"':''}>Os elementos</a>${navItem('avatares.html','Os Avatares','avatares')}<details class="atlas-nav"><summary>Explore o atlas</summary><div>${navItem('personagens.html','Personagens','personagens')}${navItem('dobras.html','Tipos de dobra','dobras')}${navItem('criaturas.html','Criaturas e espíritos','criaturas')}</div></details></nav><div class="header-actions"><button class="motion-button" id="motion-button" aria-label="Pausar animações" aria-pressed="false"><span>Ⅱ</span><small>MOVIMENTO</small></button><button class="search-button" id="open-search" aria-label="Buscar no atlas">${icon('search')}</button><button id="menu-button" class="menu-button" aria-label="Abrir navegação" aria-expanded="false">☰</button></div></div>`;
document.querySelector('#footer').innerHTML=`<div class="footer-main"><a class="brand" href="index.html">${icon('compass')}<span>ATLAS <b>AVATAR</b><small>HISTÓRIAS QUE ATRAVESSAM GERAÇÕES</small></span></a><div><a href="historia.html">A história</a><a href="avatares.html">Os Avatares</a><a href="personagens.html">Personagens</a><a href="dobras.html">Dobras</a><a href="criaturas.html">Criaturas</a><a href="fontes.html">Fontes e créditos ↗</a></div></div><div class="footer-fine"><p>Um atlas de fãs, em português. Sem vínculo com Nickelodeon ou Paramount.</p><p>Artes oficiais © Nickelodeon / Paramount. Cenários ilustrativos do atlas.</p></div>`;
function elementCards(){const arts={agua:'katara-cut.webp',terra:'toph-cut.webp',fogo:'zuko-cut.webp',ar:'aang-cut.webp'};return `<div class="element-deck">${Object.entries(ELEMENTS).map(([key,e],i)=>`<article class="spirit-card ${key}" style="--element:${e.color};--element-dark:${e.dark};--order:${i}"><div class="spirit-card-tilt"><button class="spirit-card-flip" aria-label="Revelar a carta de ${e.name}" aria-pressed="false"><span class="spirit-card-face front">${pic(arts[key],e.people[0][0])}<span class="card-shade"></span><span class="card-corner corner-a"></span><span class="card-corner corner-b"></span><span class="card-number">0${i+1}</span><span class="card-sigil">${icon(key)}</span><span class="card-title"><small>${e.quality}</small><b>${e.name}</b><i>${e.nation}</i></span><span class="flip-hint">TOQUE PARA REVELAR ⤾</span></span><span class="spirit-card-face back"><span class="card-sigil">${icon(key)}</span><span class="card-motto">${e.tag}</span><span class="card-description">${e.intro}</span><span class="flip-hint">VOLTAR À CARTA ⤾</span></span></button></div><a class="card-destination" href="${key}.html">Explorar ${e.name} <span>↗</span></a></article>`).join('')}</div>`}
function home(){return `<section class="parallax-chapter" id="novo-mundo" data-parallax-scene="sticky"><div class="painted-stage"><div class="painted-layer sky-layer" data-speed="0" data-pointer="3"><img src="assets/painted-sky.svg" alt="" fetchpriority="high"></div><div class="painted-layer far-layer" data-speed="-8" data-pointer="5"><img src="assets/painted-far.svg" alt=""></div><div class="painted-layer city-layer" data-speed="-16" data-pointer="9"><img src="assets/painted-city.svg" alt=""></div><div class="painted-layer cloud-layer" data-speed="-24" data-pointer="12"><img src="assets/painted-clouds.svg" alt=""></div><div class="painted-hero-copy" data-speed="-12" data-pointer="-2"><span class="eyebrow">QUATRO ELEMENTOS. UM NOVO HORIZONTE.</span><h1>Toda lenda<br>abre um<br><em>novo mundo.</em></h1><p>Das primeiras aventuras de Aang às descobertas de Seven Havens. Uma viagem pelas histórias que mantêm o mundo em equilíbrio.</p><a class="button primary" href="historia.html">Comece a explorar ${icon("arrow")}</a><div class="hero-element-links"><a href="agua.html" aria-label="Explorar Água">${icon("agua")}</a><a href="terra.html" aria-label="Explorar Terra">${icon("terra")}</a><a href="fogo.html" aria-label="Explorar Fogo">${icon("fogo")}</a><a href="ar.html" aria-label="Explorar Ar">${icon("ar")}</a></div></div><div class="painted-characters" data-speed="-18" data-pointer="12"><img src="assets/pavi-geet-transparent.png" alt="Pavi e Geet, recortados a partir de arte oficial" fetchpriority="high" width="1667" height="944"></div><div class="painted-layer foreground-layer" data-speed="-40" data-pointer="18"><img src="assets/hero-foreground-safe.svg" alt=""></div><div class="painted-layer petal-layer" data-speed="-46" data-pointer="20"><img src="assets/painted-petals.svg" alt=""></div><span class="scene-tag" data-speed="-18"><i></i>PAVI & GEET<span>O próximo capítulo do atlas</span></span><div class="painted-floor"><span>UM MUNDO PARA DESCOBRIR</span><a href="#elementos">Continue a viagem <span>↓</span></a><span class="scene-position">01 / 04</span></div></div></section><section class="world-intro section"><div><span class="eyebrow">UM UNIVERSO QUE NUNCA PARA</span><h2>O equilíbrio também<br>é <em>transformação.</em></h2></div><div><p>Novas pessoas. Outros caminhos. O mesmo desejo de encontrar seu lugar no mundo.</p><p>Conheça os quatro elementos, atravesse as eras e descubra o que cada Avatar deixa para a próxima geração.</p><a class="text-link" href="historia.html">Viaje pela linha do tempo ↗</a></div></section><section class="section elemental-chamber" id="elementos">${sectionHead('01 / ENCONTRE SEU ELEMENTO','Quatro formas de<br><em>sentir o mundo.</em>','<p>Toque nas cartas para revelar suas histórias.<br>Cada elemento abre um novo caminho.</p>')}${elementCards()}<span class="deck-caption">ÁGUA É MUDANÇA · TERRA É SUBSTÂNCIA · FOGO É ENERGIA · AR É LIBERDADE</span></section><section class="journey-scene" data-parallax-scene="flow"><img class="journey-clouds" src="assets/painted-clouds.svg" alt="" data-speed="55" data-pointer="8"><div class="journey-orbit" aria-hidden="true" data-speed="35"></div><div class="journey-text" data-speed="-25"><span class="eyebrow">02 / UMA JORNADA ATRAVÉS DO TEMPO</span><h2>Um menino no gelo.<br>O começo de <em>tudo.</em></h2><p>A história de Aang abriu as portas para um universo de amizade, coragem e descobertas. Cada geração encontrou seu próprio caminho.</p><a class="button" href="aang.html">Conheça a primeira jornada ${icon('arrow')}</a></div><img class="journey-aang" src="assets/aang-transparent.png" alt="Aang em posição de dobra de ar, com fundo transparente" data-speed="-125" data-pointer="25" loading="lazy"><img class="journey-petals" src="assets/painted-petals.svg" alt="" data-speed="-180" data-pointer="40"></section><section class="section eras-section">${sectionHead('03 / TODAS AS ERAS SE CONECTAM','Cada geração.<br><em>Uma nova aventura.</em>','<a class="text-link" href="historia.html">Explore a história completa ↗</a>')}<div class="era-grid"><a class="era-card" href="aang.html"><div class="era-visual">${pic('team.jpg','Equipe Avatar em A Lenda de Aang')}<span class="era-year">01</span></div><div><span class="eyebrow">A LENDA DE AANG / 3 LIVROS</span><h3>O retorno da esperança.</h3><p>Uma equipe improvável e uma jornada para encerrar uma guerra.</p><span class="text-link">Explore a era de Aang ↗</span></div></a><a class="era-card" href="korra.html"><div class="era-visual">${pic('korra.jpeg','Korra em imagem oficial')}<span class="era-year">02</span></div><div><span class="eyebrow">A LENDA DE KORRA / 4 LIVROS</span><h3>O mundo se transforma.</h3><p>Uma Avatar descobre sua força entre a cidade e os espíritos.</p><span class="text-link">Explore a era de Korra ↗</span></div></a></div></section><section class="new-era"><div class="new-era-image">${pic('havens-world.jpg','Cena oficial de Seven Havens')}</div><div class="new-era-copy"><span class="eyebrow">ALÉM DO HORIZONTE / SEVEN HAVENS</span><h2>Uma nova história<br>quer <em>ser contada.</em></h2><p>Em um mundo transformado por um cataclismo, Pavi descobre que é a nova Avatar. Seu título será o começo de uma jornada inesperada.</p><a class="button" href="seven-havens.html">Descubra Seven Havens ${icon('arrow')}</a></div></section><section class="cycle-callout"><span class="eyebrow">04 / QUEM CARREGA O EQUILÍBRIO</span><h2>Muitas vidas.<br><em>Infinitas possibilidades.</em></h2><p>Conheça as histórias de Wan, Yangchen, Kuruk, Kyoshi,<br>Roku, Aang, Korra e Pavi.</p><a href="avatares.html" class="button primary">Conheça os Avatares ${icon('arrow')}</a><div class="cycle-icons">${['agua','terra','fogo','ar'].map(k=>`<span class="${k}">${icon(k)}</span>`).join('')}</div></section>`}
function elementPage(key){const e=ELEMENTS[key];return `<div class="subnav">${elementNav()}</div><section class="element-hero" style="--element:${e.color};--element-dark:${e.dark}"><img class="element-environment" src="assets/environment-${({agua:'water',terra:'earth',fogo:'fire',ar:'air'})[key]}.svg" alt="" fetchpriority="high"><span class="landscape-credit">CENÁRIO ILUSTRATIVO DO ATLAS</span><div><a href="index.html#elementos" class="eyebrow breadcrumb">O ATLAS / OS ELEMENTOS</a><div class="element-title">${icon(key)}<h1>${e.name}</h1></div><span class="eyebrow">${e.nation.toUpperCase()} · ${e.quality.toUpperCase()}</span><h2>${e.tag}</h2><p>${e.intro}</p></div><figure>${pic(e.image,`${e.people[0][0]} na animação original`,'',true)}<figcaption>ARQUIVO OFICIAL · NICKELODEON / PARAMOUNT+</figcaption></figure></section><section class="section two-column"><div><span class="eyebrow">01 / CULTURA E TERRITÓRIO</span><h2>Um elemento.<br>Muitos caminhos.</h2><p class="lead">${e.description}</p></div><div class="place-list">${e.places.map(([name,text],i)=>`<article><span class="index">0${i+1}</span><div><h3>${name}</h3><p>${text}</p></div></article>`).join('')}</div></section><section class="section techniques-section">${sectionHead('02 / AS FORMAS DA DOBRA','Além do primeiro movimento.')}<div class="technique-grid">${e.techniques.map(([name,text],i)=>`<article><span class="tech-number">0${i+1}</span><h3>${name}</h3><p>${text}</p></article>`).join('')}</div><a class="text-link guide-link" href="dobras.html">Ver usuários, limites e episódios no guia de dobras ↗</a></section><section class="section">${sectionHead('03 / ROSTOS DESTA HISTÓRIA','Quem dá vida ao elemento.')}${elementRoster(key)}</section><section class="section two-column"><div><span class="eyebrow">04 / ATRAVÉS DAS ERAS</span><h2>${e.name} em movimento.</h2><a class="text-link" href="historia.html">Explorar a história completa ↗</a></div><div class="place-list">${e.moments.map(([name,text])=>`<article><span class="timeline-dot"></span><div><h3>${name}</h3><p>${text}</p></div></article>`).join('')}</div></section>${sources(e.sources)}<div class="next-element"><span class="eyebrow">CONTINUE EXPLORANDO</span><div class="subnav">${elementNav()}</div></div>`}
function history(){const timeline=[['O princípio','Wan e os dois mundos','A origem do Avatar é revelada em Beginnings, no segundo livro de Korra.','avatares.html','wan'],['As vidas passadas','Cada geração deixa uma marca','Yangchen, Kuruk, Kyoshi e Roku ajudam a compor o passado que antecede Aang.','avatares.html','nick'],['A Guerra dos Cem Anos','A Lenda de Aang','Um Avatar desperta em um mundo em guerra e parte para aprender os elementos.','aang.html','aang1'],['Depois da guerra','Aang adulto','O filme animado acompanha Aang e seus amigos em uma busca ligada à preservação de sua cultura.','aang.html#depois','order'],['Cerca de 70 anos depois de Aang','A Lenda de Korra','O mundo se industrializou. A nova Avatar enfrenta desafios políticos e espirituais.','korra.html','order'],['Depois de Korra','Seven Havens','Um cataclismo muda a civilização e uma nova Avatar é vista com desconfiança.','seven-havens.html','havensPress']];return `<section class="page-intro"><span class="eyebrow">O ATLAS / A HISTÓRIA</span><h1>O tempo passa.<br><em>As histórias ficam.</em></h1><p>Um percurso pelas origens, pelos sete livros de Aang e Korra e pelos novos capítulos do universo animado.</p><div class="chapter-links"><a href="aang.html">01 / Aang ↗</a><a href="korra.html">02 / Korra ↗</a><a href="seven-havens.html">03 / Seven Havens ↗</a></div></section><section class="section timeline-section">${sectionHead('01 / A ORDEM DOS ACONTECIMENTOS','Um mundo, muitas eras.')}<div class="timeline">${timeline.map(([era,title,text,href,src],i)=>`<article><div class="timeline-marker">0${i+1}</div><span class="eyebrow">${era}</span><h3>${title}</h3><p>${text}</p><a class="text-link" href="${href}">Explorar este capítulo ↗</a></article>`).join('')}</div></section><section class="section watch-order"><div><span class="eyebrow">02 / POR ONDE COMEÇAR</span><h2>Assista. Depois,<br>volte para explorar.</h2></div><div><p class="lead">Para acompanhar as séries: A Lenda de Aang → A Lenda de Korra → Seven Havens.</p><p>O filme de Aang adulto se passa entre as eras de Aang e Korra. Os romances oficiais ampliam o passado de Avatares como Kyoshi e Yangchen.</p><p>Os resumos por livro têm detalhes adicionais recolhidos. Abra cada um quando quiser avançar na trama.</p>${link('order')}</div></section>${sources(['order','wan','kyoshi','yangchen','havensPress'])}`}
function bookCard(b){return `<article class="book-card" id="livro-${b.book}"><div class="book-image">${pic(b.image,`${b.name} — ${b.subtitle}`)}<span class="book-index">${b.book}</span></div><div class="book-copy"><span class="eyebrow">LIVRO ${b.book} / ${b.name.toUpperCase()}</span><h2>${b.subtitle}</h2><p>${b.summary}</p><details><summary>Ler o arco da história <span>+ spoilers</span></summary><p>${b.details}</p></details>${link(b.source)}</div></article>`}
function series(key){const a=key==='aang';return `<section class="series-hero"><div><span class="eyebrow">O ATLAS / ${a?'A PRIMEIRA JORNADA':'UMA NOVA GERAÇÃO'}</span><h1>A Lenda<br>de <em>${a?'Aang':'Korra'}.</em></h1><p>${a?'A amizade que atravessa uma guerra. A jornada que apresenta as quatro nações e a busca de um menino por seu lugar no mundo.':'O mundo mudou. Entre a vida urbana e os espíritos, uma nova Avatar precisa descobrir o significado de equilíbrio para sua geração.'}</p><div class="series-facts"><span>${a?'2005—2008':'2012—2014'}</span><span>${a?'3 LIVROS':'4 LIVROS'}</span><span>${a?'61':'52'} EPISÓDIOS</span></div></div>${pic(a?'team.jpg':'korra.jpeg',a?'Equipe Avatar na série original':'Korra, a sucessora de Aang','',true)}</section><section class="section"><div class="section-head"><div><span class="eyebrow">A HISTÓRIA, LIVRO A LIVRO</span><h2>${a?'Aprender para transformar.':'Mudar para encontrar equilíbrio.'}</h2></div><a class="text-link" href="historia.html">← Linha do tempo</a></div><div class="books">${BOOKS.filter(b=>b.series===key).map(bookCard).join('')}</div></section>${a?`<section class="new-era" id="depois"><div class="new-era-image">${pic('aang-adulto.jpeg','Imagem oficial do filme animado de Aang adulto')}</div><div class="new-era-copy"><span class="eyebrow">ENTRE AANG E KORRA / LONGA ANIMADO</span><h2>O mundo depois da guerra.</h2><p>Avatar Aang: The Last Airbender acompanha os amigos já adultos. Uma antiga fonte de poder pode ajudar a preservar a cultura de Aang — ou cair nas mãos erradas.</p>${link('order')}</div></section>`:''}${sources(a?['aang1','aang2','aang3','order']:['korra1','korra2','korra3','korra4','order'])}<a class="wide-link" href="${a?'korra':'seven-havens'}.html"><span>PRÓXIMA ERA</span><h2>${a?'A Lenda de Korra':'Avatar: Seven Havens'}</h2>${icon('arrow')}</a>`}
function havens(){return `<section class="havens-banner">${pic('havens-hero.jpg','Pavi em imagem oficial de Seven Havens','',true)}<div><span class="eyebrow">O PRÓXIMO HORIZONTE</span><h1>Seven<br><em>Havens.</em></h1><p>A herança do Avatar.<br>O desafio de recomeçar.</p></div></section><section class="section two-column"><div><span class="eyebrow">DEPOIS DE KORRA</span><h2>Quando ser o Avatar<br>é um risco.</h2></div><div><p class="lead">Pavi, uma jovem dominadora de terra, descobre ser a próxima Avatar em um mundo devastado por um cataclismo.</p><p>Perseguida por humanos e espíritos, ela se une à irmã gêmea Nisha. As duas precisam descobrir suas origens e salvar os Sete Refúgios, os últimos grandes redutos da civilização.</p><p class="editor-note">Esta página reúne a premissa divulgada oficialmente. Não antecipa a solução dos mistérios da série.</p>${link('havensPress')}</div></section><section class="section techniques-section">${sectionHead('UMA NOVA PÁGINA DO ATLAS','O que já está confirmado.')}<div class="technique-grid"><article><span class="tech-number">01</span><h3>Uma série em 2D</h3><p>Criada por Michael Dante DiMartino e Bryan Konietzko, produzida por Avatar Studios e Nickelodeon.</p></article><article><span class="tech-number">02</span><h3>Pavi e Nisha</h3><p>Uma nova protagonista e sua irmã gêmea formam o centro do mistério de suas origens.</p></article><article><span class="tech-number">03</span><h3>A história continua</h3><p>Os dois primeiros livros somam 26 episódios. Os livros 3 e 4 também foram anunciados.</p></article></div></section><section class="section two-column"><figure>${pic('pavi.jpg','Pavi e Geet em imagem oficial')}<figcaption>© PARAMOUNT+ · MATERIAL OFICIAL DE DIVULGAÇÃO</figcaption></figure><div><span class="eyebrow">O ESTADO ATUAL DA HISTÓRIA</span><h2>Um capítulo em andamento.</h2><p>A estreia global foi anunciada para 9 de outubro de 2026 no Paramount+. O calendário do primeiro livro prevê novos blocos até 30 de outubro.</p><p>Pesquisa atualizada em 16 de outubro de 2026. Consulte o catálogo da sua região para disponibilidade.</p><a class="button primary" href="https://www.youtube.com/watch?v=nhdh962_ee0" target="_blank" rel="noopener noreferrer">Assistir ao trailer oficial ↗</a></div></section>${sources(['havens','havensPress'])}`}
function avatarCard(a){const e=ELEMENTS[a.element];return `<article class="avatar-card" data-element="${a.element}"><div class="avatar-portrait" style="--element:${e.color}">${a.image?pic(a.image,a.name):`<div class="avatar-seal">${icon(a.element)}<span>${a.name.toUpperCase()}</span><small>SELO DO ATLAS · ${e.name.toUpperCase()}</small></div>`}<span class="avatar-element">${icon(a.element)} ${e.name}</span></div><div class="avatar-copy"><span class="eyebrow">${a.era}</span><h2>${a.name}</h2><p>${a.text}</p>${link(a.source)}${portraitSource(a)}</div></article>`}
function avatars(){return `<section class="page-intro"><span class="eyebrow">O ATLAS / OS AVATARES</span><h1>Muitas vidas.<br><em>Um mesmo equilíbrio.</em></h1><p>Do primeiro Avatar à nova era. Explore as principais encarnações apresentadas nas animações e nas histórias oficiais.</p></section><section class="section avatar-section"><div class="filter-bar" role="group" aria-label="Filtrar Avatares por elemento de origem"><button class="filter active" data-filter="all" aria-pressed="true">Todos os Avatares</button>${Object.entries(ELEMENTS).map(([k,e])=>`<button class="filter" data-filter="${k}" aria-pressed="false">${icon(k)} ${e.name}</button>`).join('')}</div><p class="filter-help" id="avatar-count" aria-live="polite">8 Avatares · o filtro indica o elemento de origem.</p><div class="avatar-grid">${AVATARS.map(avatarCard).join('')}</div><p class="editor-note">Seleção das principais vidas conhecidas; não é uma lista de todas as encarnações. Wan é o início do ciclo. Entre ele e Yangchen existem muitas gerações. Os retratos consultados em arquivos de fãs têm a origem identificada junto à ficha.</p></section><section class="cycle-band"><span class="eyebrow">O CICLO DOS ELEMENTOS</span><div>${['agua','terra','fogo','ar'].map(k=>`<a href="${k}.html">${icon(k)} ${ELEMENTS[k].name}</a>`).join('<span>→</span>')}<span>↺</span></div><p>A cada vida, uma nova pessoa aprende os quatro elementos e enfrenta os desafios do seu tempo.</p></section>${sources(['wan','yangchen','kuruk','kyoshi','characters','order','havensPress'])}`}
function credits(){return `<section class="page-intro"><span class="eyebrow">O ATLAS / FONTES E CRÉDITOS</span><h1>Histórias com<br><em>origem conhecida.</em></h1><p>Conteúdo escrito em português a partir de páginas oficiais da Nickelodeon, Paramount+, editoras licenciadas e material do cocriador da série.</p></section><section class="section two-column"><div><h2>Sobre este atlas.</h2><p>Este é um projeto de fãs independente. As informações resumem os arcos das animações; as páginas de cada livro permitem abrir detalhes da trama.</p><p>A direção visual combina cenas em camadas inspiradas em KAMUI, do Studio VØR, com uma paleta clara de coral, verde-água, lilás e amarelo. Os cenários vetoriais são ilustrações originais do atlas; não representam lugares canônicos. Os fundos atuais de água, terra, fogo e ar usam polígonos, blocos e faixas de cor, desenhados em SVG para acompanhar a linguagem simples da capa. São composições decorativas do atlas, não localizações canônicas.</p><p>Pesquisa: 16 de outubro de 2026. Anúncios e disponibilidade podem variar conforme região e data.</p></div><div><h2>Arquivo de imagens.</h2><p>Os quadros e materiais promocionais são provenientes do Paramount+ e Avatar Studios. Para completar personagens, criaturas e espíritos, também foram consultadas imagens da Avatar Wiki / Fandom. Esses arquivos reproduzem quadros e artes da franquia; o link do arquivo e a página de origem estão registrados nos créditos e nas fichas. Os recortes transparentes de Pavi, Geet e Aang foram preparados com a ferramenta de imagens a partir dessas artes oficiais; são adaptações para composição, não novos materiais oficiais. Foram preservados os créditos da Nickelodeon e Paramount. Os direitos continuam com seus titulares.</p><div class="credit-list"><a href="assets/image-sources.json" target="_blank" rel="noopener noreferrer">Retratos complementares · imagens e páginas de origem ↗</a><a href="assets/visual-manifest.json" target="_blank" rel="noopener noreferrer">Recortes, ilustrações e prompts desta versão ↗</a><a href="https://www.avatarstudiosofficial.com/" target="_blank" rel="noopener noreferrer">Cenário animado e artes dos personagens · Avatar Studios ↗</a><a href="https://dribbble.com/shots/11180781-K-A-M-U-I" target="_blank" rel="noopener noreferrer">Referência de direção visual e movimento · KAMUI / Studio VØR ↗</a><a href="${SOURCES.characters.url}" target="_blank" rel="noopener noreferrer">Aang, Katara, Toph, Zuko, Iroh, Roku e equipe ↗</a><a href="${SOURCES.order.url}" target="_blank" rel="noopener noreferrer">Korra e Aang adulto ↗</a><a href="${SOURCES.havens.url}" target="_blank" rel="noopener noreferrer">Pavi, Seven Havens e Kuruk ↗</a><a href="assets/credits.json" target="_blank" rel="noopener noreferrer">Ver as URLs originais de cada imagem ↗</a></div></div></section><section class="section"><span class="eyebrow">BIBLIOTECA DE REFERÊNCIAS</span><div class="all-sources">${Object.values(SOURCES).map((s,i)=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer"><span>${String(i+1).padStart(2,'0')}</span><h3>${s.label}</h3><b>↗</b></a>`).join('')}</div></section>`}
const originalHome=home;
home=()=>originalHome().replace('<section class="section elemental-chamber"',landscape('earth','Há um mundo inteiro<br><em>entre uma aventura e outra.</em>','NOVOS CAMINHOS NO ATLAS','Explore os personagens, as formas da dobra e as criaturas que conectam as eras de Avatar.','personagens.html','Encontre os personagens')+explorationLinks()+'<section class="section elemental-chamber"');
document.querySelector('#main').innerHTML=page==='home'?home():page==='personagens'?charactersPage():page==='dobras'?bendingPage():page==='criaturas'?creaturesPage():ELEMENTS[page]?elementPage(page):page==='historia'?history():page==='avatares'?avatars():page==='seven-havens'?havens():page==='fontes'?credits():series(page);
initAtlasDirectories();
if(page==='historia'||page==='avatares'){const intro=document.querySelector('.page-intro');intro.classList.add('directory-intro');intro.style.setProperty('--directory-image',"url('assets/environment-"+(page==='historia'?'earth':'air')+".svg')");}
document.querySelector('#menu-button').addEventListener('click',e=>{const state=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',state);document.querySelector('#header').classList.toggle('menu-open',state)});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('.avatar-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.element!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#avatar-count').textContent=`${count} Avatares · ${button.dataset.filter==='all'?'todos os elementos de origem':ELEMENTS[button.dataset.filter].name}`;}));
const searchItems=[...CAST.map(c=>({title:c.name,tag:GROUPS[c.element]+' · '+ERAS[c.era],text:c.text+' '+c.skills,url:'personagens.html#'+c.id})),...BENDING.map(t=>({title:t.name,tag:'Guia de dobras',text:t.users+' '+t.text,url:'dobras.html#'+t.id})),...CREATURES.map(c=>({title:c.name,tag:c.species,text:c.text,url:'criaturas.html#'+c.id})),...Object.entries(ELEMENTS).map(([k,e])=>({title:e.name,tag:e.nation,text:e.description+' '+e.people.flat().join(' '),url:k+'.html'})),...AVATARS.map(a=>({title:a.name,tag:'Avatar · '+ELEMENTS[a.element].name,text:a.text,url:'avatares.html'})),...BOOKS.map(b=>({title:`${b.series==='aang'?'Aang':'Korra'} · Livro ${b.book}: ${b.name}`,tag:'A história',text:b.summary,url:b.series+'.html#livro-'+b.book})),{title:'Avatar: Seven Havens',tag:'Uma nova era',text:'Pavi Nisha cataclismo sete refúgios',url:'seven-havens.html'}];
document.body.insertAdjacentHTML('beforeend',`<dialog id="search-dialog"><div class="search-dialog-top"><span class="eyebrow">ENCONTRE SEU CAMINHO</span><button id="close-search" aria-label="Fechar busca">✕</button></div><label for="search-input">Buscar no atlas</label><input type="search" id="search-input" placeholder="Experimente: Toph, água, Korra…" autocomplete="off"><div id="search-results" aria-live="polite"></div></dialog>`);
const dialog=document.querySelector('#search-dialog'),input=document.querySelector('#search-input'),normalize=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function doSearch(){const q=normalize(input.value.trim());const found=q?searchItems.filter(x=>normalize(x.title+' '+x.text+' '+x.tag).includes(q)):searchItems.slice(0,4);const results=document.querySelector('#search-results');results.replaceChildren();if(!found.length){const p=document.createElement('p');p.textContent='Nenhum caminho encontrado. Tente outro personagem, elemento ou livro.';results.append(p);return;}for(const x of found){const a=document.createElement('a'),title=document.createElement('strong'),tag=document.createElement('span');a.href=x.url;title.textContent=x.title;tag.textContent=x.tag+' ↗';a.append(title,tag);results.append(a)}}
document.querySelector('#open-search').onclick=()=>{dialog.showModal();doSearch();input.focus()};document.querySelector('#close-search').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});input.addEventListener('input',doSearch);
